beforeExample:
class A {
    public int parseHex(String hexString) {
        return java.lang.Integer.valueOf(hexString, 16).intValue();
    }
}

afterExample:
class A {
    public int parseHex(String hexString) {
        return java.lang.Integer.parseInt(hexString, 16);
    }
}

negativeExample:
class A {
    public java.lang.Integer getBoxedInteger(String s, int radix) {
        // This should not match, as .intValue() is missing
        return java.lang.Integer.valueOf(s, radix);
    }

    public long parseLongHex(String hexString) {
        // This should not match, as it's a Long, not Integer
        return java.lang.Long.valueOf(hexString, 16).longValue();
    }
